function.arguments:
{"code": "import subprocess
import os

# The provided FEN
fen = "3r3k/ppp2ppp/p3b3/Q7/4n3/P2BRB1P/5PP1/7K b - - 0 1"

# Try different possible stockfish paths
stockfish_paths = [
    "/usr/games/stockfish",
    "/usr/local/bin/stockfish",
    "/usr/bin/stockfish",
    "stockfish"  # If it's in PATH
]

stockfish_path = None
for path in stockfish_paths:
    if os.path.exists(path):
        stockfish_path = path
        break
    # Also try which command
    try:
        result = subprocess.run(["which", path.split("/")[-1]], capture_output=True, text=True)
        if result.returncode == 0:
            stockfish_path = result.stdout.strip()
            break
    except Exception:
        pass

if not stockfish_path:
    print("Stockfish not found in common locations. Searching...")
    # Try to find it in PATH
    try:
        result = subprocess.run(["which", "stockfish"], capture_output=True, text=True)
        if result.returncode == 0:
            stockfish_path = result.stdout.strip()
    except Exception:
        pass

if not stockfish_path:
    print("Error: Stockfish engine not found.")
    print("Tried paths:", stockfish_paths)
    exit(1)

print(f"Found Stockfish at: {stockfish_path}")

# Set up the stockfish process
try:
    engine = subprocess.Popen(
        stockfish_path,
        universal_newlines=True,
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )

    # Send commands to stockfish
    engine.stdin.write(f"position fen {fen}\n")
    engine.stdin.write("go depth 15\n")
    engine.stdin.flush()

    # Read output
    output_lines = []
    for _ in range(50):  # Read up to 50 lines
        line = engine.stdout.readline()
        if not line:
            break
        output_lines.append(line)
        if "bestmove" in line:
            break

    # Kill the engine
    engine.terminate()
    engine.wait()

    # Parse the output
    best_move = None
    score = None

    for line in output_lines:
        if "bestmove" in line:
            parts = line.strip().split()
            if len(parts) >= 2:
                best_move = parts[1]
        elif "score cp" in line:  # Centipawn score
            parts = line.strip().split()
            for i, part in enumerate(parts):
                if part == "score" and i + 1 < len(parts) and parts[i+1] == "cp":
                    if i + 2 < len(parts):
                        try:
                            score = int(parts[i+2])
                        except:
                            pass
        elif "score mate" in line:  # Mate score
            parts = line.strip().split()
            for i, part in enumerate(parts):
                if part == "score" and i + 1 < len(parts) and parts[i+1] == "mate":
                    if i + 2 < len(parts):
                        try:
                            mate_in = int(parts[i+2])
                            score = f"mate in {mate_in}"
                        except:
                            pass

    print("Stockfish Analysis:")
    print(f"FEN: {fen}")
    if best_move:
        print(f"Best move for black: {best_move}")
    else:
        print("Could not find best move in output")

    if score:
        if isinstance(score, int):
            # Convert centipawns to pawn units
            score_in_pawns = score / 100.0
            print(f"Evaluation score: {score_in_pawns:.2f} pawns ({score} centipawns)")
        else:
            print(f"Evaluation score: {score}")
    else:
        print("Could not find evaluation score in output")

    # Print raw output for debugging
    print("\nRaw output from Stockfish:")
    for line in output_lines[:20]:
        print(line.rstrip())

except Exception as e:
    print(f"Error communicating with Stockfish: {e}")", "session_id": 1773944560}

