try:
    import chess
    import chess.engine
    print("Successfully imported chess library")
    chess_available = True
except ImportError:
    print("Chess library not available. Trying alternative approach...")
    chess_available = False

# Check for stockfish
import subprocess
import os

stockfish_path = None
try:
    # Try to find stockfish using which
    result = subprocess.run(['which', 'stockfish'], capture_output=True, text=True)
    if result.returncode == 0:
        stockfish_path = result.stdout.strip()
        print(f"Found stockfish at: {stockfish_path}")
except:
    pass

if not stockfish_path:
    # Check common locations
    common_paths = ['/usr/games/stockfish', '/usr/bin/stockfish', '/usr/local/bin/stockfish']
    for path in common_paths:
        if os.path.exists(path):
            stockfish_path = path
            print(f"Found stockfish at: {stockfish_path}")
            break

if not stockfish_path:
    print("ERROR: Could not find stockfish binary")
    print("Available commands in PATH:")
    for path in os.environ.get('PATH', '').split(':'):
        print(f"  Checking: {path}")
else:
    print(f"Stockfish binary: {stockfish_path}")

# Try to execute a simpler chess analysis if chess is available
if chess_available and stockfish_path:
    print("\n\nNow analyzing the chess position...")
    fen = "3r3k/ppp2ppp/p3b3/Q7/4n3/P2BRB1P/5PP1/7K b - - 0 1"
    board = chess.Board(fen)
    print(f"Position (Black to move):")
    print(board)

    try:
        with chess.engine.SimpleEngine.popen_uci(stockfish_path) as engine:
            result = engine.analyse(board, chess.engine.Limit(depth=20))

            # Get best move
            if "pv" in result and result["pv"]:
                best_move = result["pv"][0]
                print(f"\nBest move: {board.san(best_move)}")
            else:
                print("\nNo best move found in analysis")

            # Get evaluation
            if "score" in result:
                score = result["score"]
                if score.is_mate():
                    mate_in = score.mate()
                    print(f"Evaluation: Mate in {abs(mate_in)}")
                else:
                    cp = score.pov(chess.BLACK).score(mate_score=10000)
                    print(f"Evaluation: {cp} centipawns (from black's perspective)")
    except Exception as e:
        print(f"Error during engine analysis: {type(e).__name__}: {e}")
else:
